const API='/api/v1';
const TOKEN_KEY='parkar-auth-token';
const state={token:localStorage.getItem(TOKEN_KEY),user:null,dashboard:null,page:'home',query:'',city:'',selectedListing:null,selectedReservation:null,coveredFilter:'',camera:null,qrFrame:0,deviceHeading:null,headingHandler:null};
const roleNav={driver:[['home','Overview','⌂'],['search','Find parking','⌕'],['map','Map & route','⌖'],['bookings','My bookings','▤'],['vehicles','My vehicles','▰'],['apply','Become a provider','＋']],provider:[['home','Overview','⌂'],['listings','My listings','▧'],['layout','Space layout','▥'],['pricing','Pricing & discounts','₱'],['checkpoints','Indoor checkpoints','▦'],['reservations','Reservations','▤'],['measure','AR mapping','◎'],['memberships','Memberships','♙']],admin:[['home','Overview','⌂'],['review','Provider review','✓'],['moderate','Listings','▧'],['users','Users','♙'],['reports','Reports','▥']]};
const $=(selector,root=document)=>root.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
function money(value){return new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP',maximumFractionDigits:2}).format(Number(value||0))}
function fmtDate(value){return value?new Date(value).toLocaleString('en-PH',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'}):'—'}
function showToast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>el.classList.remove('show'),3200)}
async function api(path,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};if(state.token)headers.Authorization=`Token ${state.token}`;let response;try{response=await fetch(`${API}${path}`,{...options,headers,body:options.body&&typeof options.body!=='string'?JSON.stringify(options.body):options.body})}catch{throw new Error('The ParkAR server could not be reached. Check that the application is running and try again.')}if(response.status===401){state.token=null;localStorage.removeItem(TOKEN_KEY);state.user=null;render();throw new Error('Your session ended. Sign in again.')}if(response.status===204)return null;let result={};try{result=await response.json()}catch{}if(!response.ok){let message=result.detail||Object.entries(result).map(([k,v])=>`${k}: ${Array.isArray(v)?v.join(', '):typeof v==='object'?JSON.stringify(v):v}`).join('\n')||'The request could not be completed.';throw new Error(message)}return result}
async function refresh(){state.dashboard=await api('/dashboard/');state.user=state.dashboard.user;render()}
function role(){return state.user?.role||'driver'}
function enter(data){state.token=data.token;localStorage.setItem(TOKEN_KEY,data.token);state.user=data.user;state.page='home';refresh().catch(err=>showToast(err.message))}
function logout(){stopCamera();api('/auth/logout/',{method:'POST'}).catch(()=>{});localStorage.removeItem(TOKEN_KEY);state.token=null;state.user=null;state.dashboard=null;render()}
function nav(){return `<nav aria-label="Main navigation">${roleNav[role()].map(([key,label,icon])=>`<button data-page="${key}" class="${state.page===key?'active':''}"><span class="nav-icon">${icon}</span><span class="nav-text">${label}</span></button>`).join('')}</nav>`}
function shell(content){return `<div class="app-shell"><aside class="sidebar"><a class="brand" href="#"><span class="brand-mark">P</span><span>Park<span class="brand-light">AR</span><small>SPACE, FOUND.</small></span></a><div class="role-switch"><label>ACCOUNT</label><div class="sidebar-account">${esc(state.user?.first_name||state.user?.username)}<small>${esc(role().toUpperCase())}</small></div></div>${nav()}<div class="sidebar-bottom"><div><span class="offline-dot"></span><span>Connected to ParkAR</span></div><div class="profile"><div class="avatar" style="cursor:pointer" data-action="account-settings" title="Account settings">${esc((state.user?.first_name||state.user?.username||'P').slice(0,1).toUpperCase())}</div><div style="cursor:pointer" data-action="account-settings" title="Account settings"><b>${esc(state.user?.email||state.user?.username)}</b><small>⚙ Settings</small></div><button data-action="logout" title="Sign out">↪</button></div></div></aside><main class="main"><header class="topbar"><div><span class="eyebrow">PARKING, SIMPLIFIED</span><h1>${esc(pageTitle())}</h1></div><div class="top-actions"><button class="button outline small" data-action="account-settings">⚙ Profile</button><button class="icon-btn" data-action="notifications" aria-label="Notifications">♧</button><div class="top-avatar" style="cursor:pointer" data-action="account-settings" title="Account settings">${esc((state.user?.first_name||state.user?.username||'P').slice(0,1).toUpperCase())}</div></div></header><div id="view" class="view">${content}</div></main></div>`}
function pageTitle(){return ({home:role()==='driver'?'Find a space':role()==='provider'?'Provider overview':'Operations overview',search:'Find parking',map:'Map & route',bookings:'My bookings',vehicles:'My vehicles',apply:'Provider application',listings:'My listings',layout:'Parking layout',pricing:'Pricing & discounts',checkpoints:'Indoor checkpoints',reservations:'Reservations',measure:'AR mapping',memberships:'Memberships',review:'Provider review',moderate:'Listing moderation',users:'Platform users',reports:'Reports'})[state.page]||'ParkAR'}
function render(){if(state.page!=='guide')stopHeading();if(state.camera&&!['guide','measure'].includes(state.page))stopCamera();const root=$('#appRoot');if(!state.token){root.innerHTML=authView();bind();return}root.innerHTML=shell(pageView());bind();if(state.page==='layout')drawParking3d();if(state.page==='map')setTimeout(()=>window.dispatchEvent(new CustomEvent('parkar:map-data',{detail:{listings:listings(),route:state.routeData||null}})),0)}
function authView(){const mode=state.authMode||'login',brand='<div class="auth-brand"><span class="brand-mark">P</span><span>Park<span class="brand-light">AR</span></span></div>';
 if(mode==='forgot')return `<main class="auth-page"><section class="auth-card">${brand}<div class="eyebrow">ACCOUNT RECOVERY</div><h1>Reset your password</h1><p class="section-sub">Enter the email address on your ParkAR account. We’ll send a one-time reset link if it matches an account.</p><form id="forgotForm"><div class="field"><label>Email</label><input class="input" name="email" type="email" autocomplete="email" required></div><button class="button" style="width:100%">Send reset link</button><p id="authNotice" class="auth-notice">${state.authNotice||''}</p><p id="authError" class="form-error"></p></form><button class="text-link auth-back" type="button" data-auth-tab="login">← Back to sign in</button></section></main>`;
 if(mode==='reset')return `<main class="auth-page"><section class="auth-card">${brand}<div class="eyebrow">ACCOUNT RECOVERY</div><h1>Choose a new password</h1><p class="section-sub">Use a password with at least 10 characters that you have not used before.</p><form id="resetForm"><input type="hidden" name="uid" value="${esc(state.resetUid||'')}"><input type="hidden" name="token" value="${esc(state.resetToken||'')}"><div class="field"><label>New password</label><input class="input" name="password" type="password" autocomplete="new-password" minlength="10" required></div><div class="field"><label>Confirm new password</label><input class="input" name="confirm_password" type="password" autocomplete="new-password" minlength="10" required></div><button class="button" style="width:100%">Update password</button><p id="authNotice" class="auth-notice">${esc(state.authNotice||'')}</p><p id="authError" class="form-error"></p></form><button class="text-link auth-back" type="button" data-auth-tab="login">← Back to sign in</button></section></main>`;
 const registering=mode==='register';return `<main class="auth-page"><section class="auth-card">${brand}<div class="eyebrow">PARKING, SIMPLIFIED</div><h1>Welcome to ParkAR</h1><p class="section-sub">Sign in to find parking, manage listings, or review provider applications.</p><div class="auth-tabs"><button class="${registering?'':'active'}" data-auth-tab="login">Sign in</button><button class="${registering?'active':''}" data-auth-tab="register">Create account</button></div><form id="authForm"><div class="field"><label>Email</label><input class="input" name="email" type="email" autocomplete="email" required></div><div id="nameFields" class="${registering?'':'hidden-section'}"><div class="field"><label>Username</label><input class="input" name="username" autocomplete="username"></div><div class="field"><label>First name</label><input class="input" name="first_name" autocomplete="given-name"></div><div class="field"><label>Last name</label><input class="input" name="last_name" autocomplete="family-name"></div></div><div class="field"><div style="display:flex;justify-content:space-between;align-items:center"><label style="margin:0">Password</label><button class="text-link auth-forgot" type="button" data-auth-tab="forgot" style="margin:0;font-size:12px;cursor:pointer">Forgot password?</button></div><input class="input" name="password" type="password" autocomplete="${registering?'new-password':'current-password'}" minlength="${registering?'10':'1'}" required></div><button class="button" id="authSubmit" style="width:100%;margin-top:8px">${registering?'Create driver account':'Sign in'}</button><p id="authNotice" class="auth-notice">${esc(state.authNotice||'')}</p><p id="authError" class="form-error"></p></form><p class="footer-note">Accounts are protected with server-side password hashing and role-based access.</p></section></main>`}
function pageView(){if(!state.dashboard)return `<div class="panel">Loading your workspace…</div>`;const pages={home:homeView,search:searchView,map:mapView,bookings:bookingsView,guide:guideView,vehicles:vehiclesView,apply:applicationView,listings:listingsView,layout:layoutView,pricing:pricingView,checkpoints:checkpointsView,reservations:reservationsView,measure:measureView,memberships:membershipsView,review:reviewView,moderate:moderateView,users:usersView,reports:reportsView};return(pages[state.page]||homeView)()}
function listings(){return state.dashboard.listings||[]}
function bookings(){return state.dashboard.reservations||[]}
function listing(id){return listings().find(l=>String(l.id)===String(id))||state.selectedListing}
function price(listing){return `${money(listing.hourly_rate)}<small> / hour</small>`}
function card(l){let open=l.available_count??l.spaces?.filter(s=>s.status==='available').length??0;return `<article class="listing-card"><div class="listing-image"><div class="listing-illustration"><span class="building b1"></span><span class="building b2"></span><span class="car-illus">P</span><span class="road-line"></span></div><span class="tag">${l.covered?'Covered':'Open-air'}</span><span class="tag available">● ${open} spaces</span></div><div class="listing-body"><div class="listing-title-row"><div class="listing-title">${esc(l.name)}</div><div class="price">${price(l)}</div></div><div class="meta"><span>⌖ ${esc(l.city)}</span><span>${esc(l.address)}</span></div><div class="card-footer"><span class="capacity"><b>${open} available</b> · ${esc(l.status)}</span><div><button class="button outline small" style="margin-right:6px" data-action="view-layout-preview" data-id="${l.id}">View bays</button><button class="button small" data-action="book" data-id="${l.id}">Reserve</button></div></div></div></article>`}
function stat(label,value,caption,icon='↗'){return `<div class="stat"><span class="spark">${icon}</span><span class="label">${label}</span><strong>${value}</strong><small>${caption}</small></div>`}
function homeView(){if(role()==='driver'){const d=state.dashboard,active=bookings().filter(b=>b.status==='confirmed');return `<section class="welcome"><div><span class="eyebrow">WELCOME, ${esc((state.user.first_name||state.user.username).toUpperCase())}</span><h2>Find the right spot.<br>Arrive with a plan.</h2><p>Browse verified parking, reserve for your vehicles, and get indoor directions to your assigned bay.</p><button class="button lime" data-page="search">Explore parking →</button></div><div class="welcome-right"><div class="parking-art"></div></div></section><div class="stats">${stat('ACTIVE LOCATIONS',listings().length,'Verified parking providers','⌖')}${stat('UPCOMING BOOKINGS',active.length,'Confirmed reservations','◷')}${stat('MY VEHICLES',d.vehicles.length,'Saved vehicle profiles','▰')}${stat('UNREAD UPDATES',d.notifications.filter(n=>!n.read_at).length,'Booking and account notices','♧')}</div><div class="content-grid"><section class="panel"><div class="panel-head"><div><h3 class="section-title">Available parking</h3><p class="section-sub">Verified listings ready to reserve</p></div><button class="text-link" data-page="search">Browse all →</button></div><div class="listing-list">${listings().slice(0,2).map(card).join('')||'<div class="empty">No active parking listings yet.</div>'}</div></section><section class="panel"><div class="panel-head"><div><h3 class="section-title">Upcoming bookings</h3><p class="section-sub">Your confirmed parking</p></div><button class="text-link" data-page="bookings">View all →</button></div>${active.slice(0,4).map(bookingRow).join('')||'<div class="empty">No bookings yet. Find a space to get started.</div>'}</section></div>`}return role()==='provider'?providerDashboardView():adminDashboardView()}
function providerDashboardView(){const d=state.dashboard,confirmed=bookings().filter(b=>b.status==='confirmed'),pendingPayments=bookings().reduce((n,b)=>n+(b.payments||[]).filter(p=>p.status==='pending').length,0),activeListings=listings().filter(l=>l.status==='active').length;return `<div class="provider-dashboard"><section class="welcome"><div><span class="eyebrow">PROVIDER WORKSPACE</span><h2>Manage your parking<br>business from here.</h2><p>Update your locations, space layouts, prices, and indoor checkpoints. Track reservations as they arrive.</p><button class="button lime" data-action="new-listing">+ Add a parking location</button></div><div class="welcome-right"><div class="parking-art"></div></div></section><div class="stats">${stat('MY LOCATIONS',listings().length,`${activeListings} active and visible to drivers`,'▧')}${stat('CONFIRMED BOOKINGS',confirmed.length,'Across your parking locations','◷')}${stat('PAYMENTS TO RECORD',pendingPayments,'Awaiting collection confirmation','₱')}${stat('UNREAD UPDATES',d.notifications.filter(n=>!n.read_at).length,'New activity','♧')}</div><section class="panel dashboard-section"><div class="panel-head"><div><h3 class="section-title">Provider tools</h3><p class="section-sub">Jump directly to the work you need to do.</p></div></div><div class="dashboard-shortcuts"><button class="dashboard-shortcut" data-page="listings"><span>▧</span><b>My locations</b><small>Create and update parking listings</small></button><button class="dashboard-shortcut" data-page="layout"><span>▦</span><b>Space layout</b><small>Manage bays and availability</small></button><button class="dashboard-shortcut" data-page="pricing"><span>₱</span><b>Pricing</b><small>Set rates and discounts</small></button><button class="dashboard-shortcut" data-page="checkpoints"><span>⌖</span><b>Indoor checkpoints</b><small>Set up QR route markers</small></button><button class="dashboard-shortcut" data-page="reservations"><span>▤</span><b>Reservations</b><small>View bookings and payments</small></button><button class="dashboard-shortcut" data-page="measure"><span>◎</span><b>AR mapping</b><small>Review lot boundaries and dimensions</small></button></div></section><section class="panel dashboard-section"><div class="panel-head"><div><h3 class="section-title">Recent reservations</h3><p class="section-sub">Latest customer bookings</p></div><button class="text-link" data-page="reservations">View all →</button></div>${bookings().slice(0,6).map(bookingRow).join('')||'<div class="empty">No reservations yet. Your bookings will appear here.</div>'}</section></div>`}
function adminDashboardView(){const d=state.dashboard,pending=(d.applications||[]).filter(a=>a.status==='pending');return `<div class="admin-dashboard"><section class="welcome"><div><span class="eyebrow">ADMINISTRATION</span><h2>ParkAR platform<br>control center.</h2><p>Review provider access, approve parking locations, and monitor platform activity.</p><button class="button lime" data-page="review">Review ${pending.length} pending application${pending.length===1?'':'s'} →</button></div><div class="welcome-right"><div class="parking-art"></div></div></section><div class="stats">${stat('REGISTERED USERS',d.counts.users??'—','Driver and provider accounts','♙')}${stat('VERIFIED PROVIDERS',d.counts.providers??'—','Approved provider accounts','✓')}${stat('PENDING APPLICATIONS',d.counts.pending_applications??'—','Awaiting review','◷')}${stat('TOTAL BOOKINGS',bookings().length,'Platform activity','▤')}</div><section class="panel dashboard-section"><div class="panel-head"><div><h3 class="section-title">Administration tools</h3><p class="section-sub">Manage access, listings, and reporting.</p></div></div><div class="dashboard-shortcuts"><button class="dashboard-shortcut" data-page="review"><span>✓</span><b>Provider review</b><small>${pending.length} applications awaiting review</small></button><button class="dashboard-shortcut" data-page="moderate"><span>▧</span><b>Listing approvals</b><small>Review parking locations before publishing</small></button><button class="dashboard-shortcut" data-page="users"><span>♙</span><b>Platform users</b><small>View account roles and access</small></button><button class="dashboard-shortcut" data-page="reports"><span>▤</span><b>Reports</b><small>Review bookings and platform activity</small></button></div></section><section class="panel dashboard-section"><div class="panel-head"><div><h3 class="section-title">Applications needing review</h3><p class="section-sub">Provider access requests awaiting a decision.</p></div><button class="text-link" data-page="review">Open queue →</button></div><div class="admin-queue">${pending.slice(0,5).map(applicationRow).join('')||'<div class="empty">No applications are waiting for review.</div>'}</div></section></div>`}
function bookingRow(b){return `<div class="booking-item"><div class="booking-icon">▰</div><div class="booking-info"><b>${esc(b.listing_name)} · ${esc(b.code)}</b><small>${fmtDate(b.starts_at)} · Bay ${(b.assignments||[]).map(a=>esc(a.code)).join(', ')||'pending'}</small></div><span class="status ${b.status==='cancelled'?'cancelled':''}">${esc(b.status)}</span></div>`}
function searchView(){return `<div class="row"><div><h2 class="section-title">Search available parking</h2><p class="section-sub">Filter by area and parking type. Results come from active listings.</p></div><button class="button outline" data-page="map">⌖ Map view</button></div><form class="filterbar" id="searchForm"><label class="search"><span>⌕</span><input name="q" placeholder="Parking name, street, or city" value="${esc(state.query)}"></label><input class="input" name="city" placeholder="City" value="${esc(state.city)}" style="max-width:180px"><select name="covered"><option value="">Any parking</option><option value="true">Covered</option><option value="false">Open-air</option></select><button class="button small">Search</button></form><div class="listing-grid">${listings().map(card).join('')||'<div class="empty">No available listings match your filters.</div>'}</div>`}
function mapView(){const items=listings();return `<div class="row"><div><h2 class="section-title">3D parking map & route</h2><p class="section-sub">Browse geocoded parking locations and launch a route preview.</p></div><button class="button outline" data-action="locate">◎ Use my location</button></div><div class="map-layout" style="margin-top:16px"><div id="liveMap" class="map-live" aria-label="Interactive 3D parking map"></div><section class="panel map-side"><div class="panel-head"><h3 class="section-title">Active locations</h3><span class="tag">${items.length}</span></div>${items.map(l=>`<div class="map-result"><div><b>${esc(l.name)}</b><small>${esc(l.address)} · ${l.available_count??0} available</small></div><button class="button small" data-action="route-preview" data-id="${l.id}">Route</button> <button class="button outline small" data-action="external-route" data-id="${l.id}">Open map</button></div>`).join('')||'<div class="empty">No active listings.</div>'}<p class="footer-note">3D buildings and route geometry require online map data. Configure a production tile and routing service before public deployment.</p></section></div>`}
function bookingsView(){return `<div class="row"><div><h2 class="section-title">Reservations</h2><p class="section-sub">Bookings, assigned bays, payments and indoor guidance.</p></div><button class="button" data-page="search">+ Find parking</button></div><div class="panel" style="margin-top:16px">${bookings().length?`<table class="table"><thead><tr><th>RESERVATION</th><th>LOCATION</th><th>SCHEDULE</th><th>BAYS</th><th>TOTAL</th><th>PAYMENT</th><th>ACTIONS</th></tr></thead><tbody>${bookings().map(b=>`<tr><td><b>${esc(b.code)}</b><small>${esc(b.status)}</small></td><td>${esc(b.listing_name)}<small>${esc(b.listing_address)}</small></td><td>${fmtDate(b.starts_at)}<small>until ${fmtDate(b.ends_at)}</small></td><td>${(b.assignments||[]).map(a=>esc(a.code)).join(', ')||'—'}</td><td><b>${money(b.total)}</b></td><td>${(b.payments||[]).map(p=>`<span class="status ${p.status==='pending'?'pending':''}">${esc(p.status)}</span>`).join(' ')||'—'}</td><td><button class="button outline small" data-action="ticket" data-id="${b.id}">🎟 Pass</button> ${b.status==='confirmed'?`<button class="button lime small" data-action="guide" data-id="${b.id}">◎ Guide</button> <button class="button danger small" data-action="cancel" data-id="${b.id}">Cancel</button>`:''}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No reservations have been made on this account.</div>'}</div>`}
function vehiclesView(){return `<div class="row"><div><h2 class="section-title">Vehicle profiles</h2><p class="section-sub">Add your vehicles before making a reservation.</p></div><button class="button" data-action="add-vehicle">+ Add vehicle</button></div><div class="listing-grid" style="margin-top:16px">${state.dashboard.vehicles.map(v=>`<div class="panel"><span class="tag">${esc(v.category)}</span><h3 class="section-title" style="margin-top:12px">${esc(v.name)}</h3><p class="section-sub">${esc(v.plate_number)} · ${v.length_m}m × ${v.width_m}m</p><button class="button danger small" data-action="remove-vehicle" data-id="${v.id}">Remove</button></div>`).join('')||'<div class="empty">Add a vehicle profile to book a space.</div>'}</div>`}
function applicationView(){const own=state.dashboard.applications.at(-1);return `<div class="content-grid"><section class="panel"><h2 class="section-title">Become a parking provider</h2><p class="section-sub">Submit your details for administrator review. Provider tools unlock after approval.</p>${own?`<div class="summary-box"><div class="summary-row"><span>Latest application</span><b>${esc(own.status)}</b></div><div class="summary-row"><span>Submitted</span><b>${fmtDate(own.created_at)}</b></div></div>`:''}<form id="applicationForm" class="listing-form" style="margin-top:16px"><div class="field"><label>Legal name</label><input class="input" name="legal_name" required></div><div class="field"><label>Business name (if applicable)</label><input class="input" name="business_name"></div><div class="field"><label>Contact phone</label><input class="input" name="contact_phone" required></div><div class="field full"><label>Provider address</label><textarea name="address" required></textarea></div><div class="field full"><label>Additional information</label><textarea name="notes"></textarea></div><button class="button">Submit application</button></form></section><section class="panel"><h3 class="section-title">Provider access</h3><p class="section-sub">Verified providers can publish parking locations, manage rates and parking layouts, assign indoor checkpoints, and record reservation payments.</p><div class="summary-box"><b>Application status</b><p class="section-sub">${own?esc(own.status):'No application submitted yet.'}</p></div></section></div>`}
function listingsView(){return `<div class="row"><div><h2 class="section-title">Your parking listings</h2><p class="section-sub">New listings enter administrator review before appearing publicly.</p></div><button class="button" data-action="new-listing">+ Create listing</button></div><div class="listing-grid" style="margin-top:16px">${listings().map(l=>`<div class="panel"><div class="row"><span class="tag">${esc(l.status)}</span><b>${price(l)}</b></div><h3 class="section-title" style="margin-top:12px">${esc(l.name)}</h3><p class="section-sub">${esc(l.address)} · ${esc(l.city)}</p><div class="row" style="margin-top:14px"><span class="capacity">${l.spaces?.length||0} spaces · layout v${l.current_layout_version}</span><button class="button outline small" data-action="select-listing" data-id="${l.id}">Manage</button></div></div>`).join('')||'<div class="empty">No listings yet. Create a listing to start.</div>'}</div>`}
function selectedProviderListing(){return listings().find(l=>l.id===state.selectedListing?.id)||listings()[0]}
function layoutView(){let l=selectedProviderListing();if(!l)return `<div class="panel empty">Create a listing before editing its layout.</div>`;let spaces=l.spaces||[];return `<div class="row"><div><h2 class="section-title">${esc(l.name)} · parking layout</h2><p class="section-sub">Configure stable bay codes, vehicle compatibility and dimensions.</p></div><button class="button outline" data-action="edit-checkpoints" data-id="${l.id}">Indoor checkpoints →</button></div><div class="provider-layout" style="margin-top:16px"><section class="panel"><div class="layout-top"><span class="tag">${spaces.length} configured spaces</span><div><button class="button small" data-action="add-space">+ Add bay</button></div></div><div class="layout-3d-wrap"><canvas id="layout3d" aria-label="Interactive three-dimensional parking lot layout"></canvas><span class="tag">3D layout · drag to rotate</span></div><div class="space-grid">${spaces.map(s=>`<div class="space-wrap"><button class="space ${s.status==='blocked'?'occupied':''} ${s.is_accessible?'accessible':''}" data-action="cycle-space" data-id="${s.id}" title="${esc(s.status)} · click to change">${esc(s.code)}<small>${esc(s.vehicle_class)} · ${s.width_m}m×${s.length_m}m</small></button><div style="display:flex;gap:4px;justify-content:space-between;margin-top:2px"><button class="access-toggle" data-action="toggle-accessible" data-id="${s.id}" title="Toggle accessible space">${s.is_accessible?'♿':'+'}</button><button class="text-link" style="font-size:10px" data-action="edit-space" data-id="${s.id}">Edit</button><button class="text-link danger" style="font-size:10px;color:#c53030" data-action="delete-space" data-id="${s.id}">✕</button></div></div>`).join('')||'<div class="empty">Add at least one space to your lot.</div>'}</div><div class="legend"><span>Available</span><span>Provider blocked</span><span>Reservations are allocated by schedule</span></div><button class="button" style="margin-top:16px" data-action="save-layout">Save layout</button></section><section class="panel"><h3 class="section-title">Layout dimensions</h3><form id="measurementForm" class="listing-form" style="margin-top:14px"><input type="hidden" name="listing_id" value="${l.id}"><div class="field"><label>Lot width (m)</label><input class="input" name="width_m" type="number" min="1" step="0.1" value="${l.width_m||''}" required></div><div class="field"><label>Lot length (m)</label><input class="input" name="length_m" type="number" min="1" step="0.1" value="${l.length_m||''}" required></div><div class="field full"><label>Source</label><select name="source"><option value="manual">Manually measured</option><option value="camera_estimate">Camera-assisted estimate</option></select></div><button class="button">Save dimensions</button></form><p class="footer-note">Camera estimates are not survey-grade. Providers confirm all dimensions before they are used for capacity configuration.</p></section></div>`}
function drawParking3d(){const canvas=$('#layout3d');const l=selectedProviderListing();if(!canvas||!l)return;const spaces=l.spaces||[],rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=Math.max(1,Math.round(rect.width*dpr));canvas.height=Math.max(1,Math.round(rect.height*dpr));const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);const w=rect.width,h=rect.height;ctx.clearRect(0,0,w,h);if(!spaces.length){ctx.fillStyle='#647469';ctx.font='13px Arial';ctx.fillText('Add parking bays to build the 3D layout',18,30);return}const cols=Math.max(1,...spaces.map(s=>Number(s.grid_column)+1)),rows=Math.max(1,...spaces.map(s=>Number(s.grid_row)+1)),unit=Math.min(34,(w-80)/(cols+rows+2));const yaw=state.layoutYaw||-.48,pitch=state.layoutPitch||.72,cx=w/2,baseY=h*.72;const project=(x,y,z)=>{const xx=x*Math.cos(yaw)-z*Math.sin(yaw),zz=x*Math.sin(yaw)+z*Math.cos(yaw);return [cx+xx*unit,baseY+zz*unit*Math.cos(pitch)-y*unit*Math.sin(pitch)]};const poly=(points,fill,stroke='#73846f')=>{ctx.beginPath();points.forEach((p,i)=>{const q=project(...p);if(i)ctx.lineTo(q[0],q[1]);else ctx.moveTo(q[0],q[1])});ctx.closePath();ctx.fillStyle=fill;ctx.fill();ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()};const car=(x,z)=>{const y0=.12,y1=.48,dx=.27,dz=.33;poly([[x-dx,y0,z-dz],[x+dx,y0,z-dz],[x+dx,y1,z-dz],[x-dx,y1,z-dz]],'#789879');poly([[x+dx,y0,z-dz],[x+dx,y0,z+dz],[x+dx,y1,z+dz],[x+dx,y1,z-dz]],'#4d7054');poly([[x-dx,y1,z-dz],[x+dx,y1,z-dz],[x+dx,y1,z+dz],[x-dx,y1,z+dz]],'#8ba989','#edf4e8')};const deckX=cols*.55,deckZ=rows*.55;poly([[-deckX,-.22,-deckZ],[deckX,-.22,-deckZ],[deckX,-.22,deckZ],[-deckX,-.22,deckZ]],'#d8e1d4','#97a893');const ordered=[...spaces].sort((a,b)=>(a.grid_row+a.grid_column)-(b.grid_row+b.grid_column));for(const s of ordered){const x=Number(s.grid_column)-(cols-1)/2,z=Number(s.grid_row)-(rows-1)/2,dx=.44,dz=.42;let color=s.status==='blocked'?'#d3d8d0':s.status==='reserved'?'#f2d7a5':s.is_accessible?'#d8edc1':'#edf2e9';poly([[x-dx,-.10,z-dz],[x+dx,-.10,z-dz],[x+dx,.03,z-dz],[x-dx,.03,z-dz]],'#bac8b5');poly([[x+dx,-.10,z-dz],[x+dx,-.10,z+dz],[x+dx,.03,z+dz],[x+dx,.03,z-dz]],'#a7b7a3');poly([[x-dx,.03,z-dz],[x+dx,.03,z-dz],[x+dx,.03,z+dz],[x-dx,.03,z+dz]],color,'#879a80');if(s.status==='reserved')car(x,z);const p=project(x,.18,z);ctx.fillStyle='#35513b';ctx.font='600 9px Arial';ctx.textAlign='center';ctx.fillText(s.code,p[0],p[1]-5)}canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);canvas.dataset.dragX=e.clientX;canvas.onpointermove=move=>{if(!canvas.hasPointerCapture(move.pointerId))return;const prev=Number(canvas.dataset.dragX)||move.clientX;state.layoutYaw=(state.layoutYaw||-.48)+(move.clientX-prev)*.008;canvas.dataset.dragX=move.clientX;drawParking3d()};canvas.onpointerup=canvas.onpointercancel=()=>{canvas.onpointermove=null}};canvas.onwheel=e=>{e.preventDefault();state.layoutPitch=Math.max(.36,Math.min(1.15,(state.layoutPitch||.72)-e.deltaY*.001));drawParking3d()};if(!state.layoutResizeBound){window.addEventListener('resize',drawParking3d);state.layoutResizeBound=true}}
function pricingView(){let l=selectedProviderListing();if(!l)return '<div class="empty">Create a listing to configure rates.</div>';return `<div class="row"><div><h2 class="section-title">Rates & discounts · ${esc(l.name)}</h2><p class="section-sub">Set the listing base rate and optional vehicle-specific pricing rules.</p></div></div><div class="content-grid" style="margin-top:16px"><section class="panel"><h3 class="section-title">Base hourly rate</h3><p class="section-sub">${money(l.hourly_rate)} per hour before any applicable rule.</p><form id="baseRateForm" class="listing-form"><input type="hidden" name="listing_id" value="${l.id}"><div class="field"><label>Rate (PHP / hour)</label><input class="input" name="hourly_rate" type="number" min="0.01" step="0.01" value="${l.hourly_rate}" required></div><button class="button">Save base rate</button></form></section><section class="panel"><div class="panel-head"><h3 class="section-title">Add a pricing rule</h3></div><form id="priceRuleForm" class="listing-form"><input type="hidden" name="listing_id" value="${l.id}"><div class="field full"><label>Rule name</label><input class="input" name="name" required></div><div class="field"><label>Vehicle category</label><select name="vehicle_category"><option value="">All vehicles</option><option value="motorcycle">Motorcycle</option><option value="car">Car</option><option value="suv">SUV</option><option value="van">Van</option></select></div><div class="field"><label>Hourly rate (PHP)</label><input class="input" type="number" name="hourly_rate" min="0.01" step="0.01" required></div><div class="field"><label>Discount (%)</label><input class="input" type="number" name="discount_percent" min="0" max="100" step="0.01" value="0"></div><div class="field"><label>Active</label><select name="active"><option value="true">Yes</option><option value="false">No</option></select></div><div class="field"><label>Starts at (optional)</label><input class="input" type="time" name="start_time"></div><div class="field"><label>Ends at (optional)</label><input class="input" type="time" name="end_time"></div><div class="field full"><button class="button">Save pricing rule</button></div></form></section></div><section class="panel" style="margin-top:16px"><div class="panel-head"><h3 class="section-title">Configured rules</h3></div><div id="priceRuleList" class="empty">Loading pricing rules…</div></section>`}
function checkpointsView(){let l=selectedProviderListing();if(!l)return '<div class="empty">Create a listing first.</div>';return `<div class="row"><div><h2 class="section-title">Indoor checkpoints · ${esc(l.name)}</h2><p class="section-sub">Connect QR checkpoint locations to the assigned parking bay.</p></div><button class="button outline" data-action="select-listing">Change lot</button></div><div class="content-grid" style="margin-top:16px"><section class="panel"><div class="panel-head"><h3 class="section-title">Checkpoint markers</h3><button class="button small" data-action="add-checkpoint">+ Add checkpoint</button></div><div id="checkpointList"><div class="empty">Loading checkpoints…</div></div></section><section class="panel"><h3 class="section-title">Connect aisle route</h3><p class="section-sub">Add a route between two checkpoints. Edges default to two-way walking or driving access.</p><form id="edgeForm" class="listing-form"><input type="hidden" name="listing_id" value="${l.id}"><div class="field"><label>From checkpoint code</label><input class="input" name="from_code" placeholder="JUNCTION" required></div><div class="field"><label>To checkpoint code</label><input class="input" name="to_code" placeholder="ROW-A" required></div><div class="field"><label>Approx. distance (m)</label><input class="input" type="number" min="0.1" step="0.1" name="distance_m" value="8" required></div><div class="field full"><label>Direction instruction</label><input class="input" name="instruction" value="Follow the aisle markers." required></div><button class="button">Connect route</button></form><p class="footer-note">Scan code format: <code>PARKAR|listing-id|checkpoint-code</code>. Create and print a QR sticker with that text for each marker.</p></section></div>`}
function reservationsView(){return `<div class="row"><div><h2 class="section-title">Parking reservations</h2><p class="section-sub">Bookings for your listings, with payment collection status.</p></div><button class="button outline" data-page="memberships">Manage memberships</button></div><div class="panel" style="margin-top:16px">${bookings().length?`<table class="table"><thead><tr><th>BOOKING</th><th>DRIVER / LISTING</th><th>SCHEDULE</th><th>ASSIGNED BAY</th><th>TOTAL</th><th>PAYMENT</th><th></th></tr></thead><tbody>${bookings().map(b=>`<tr><td><b>${esc(b.code)}</b><small>${esc(b.status)}</small></td><td>${esc(b.vehicles?.map(v=>v.vehicle_name).join(', ')||'Driver')}<small>${esc(b.listing_name)}</small></td><td>${fmtDate(b.starts_at)}<small>to ${fmtDate(b.ends_at)}</small></td><td>${(b.assignments||[]).map(a=>esc(a.code)).join(', ')}</td><td>${money(b.total)}</td><td>${(b.payments||[]).map(p=>p.status==='pending'?`<button class="button small" data-action="mark-paid" data-id="${p.id}">Mark paid</button>`:`<span class="status">${esc(p.status)}</span>`).join(' ')}</td><td></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No reservations to display.</div>'}</div>`}
function measureView(){let l=selectedProviderListing();if(!l)return '<div class="empty">Create a listing first.</div>';return `<div class="row"><div><h2 class="section-title">AR-assisted lot mapping & bay layout</h2><p class="section-sub">Use live camera markers to measure lot bounds and auto-calculate parking bay layouts.</p></div><span class="tag">AR assisted</span></div><div class="provider-layout" style="margin-top:16px"><section class="panel"><div id="cameraStage" class="ar-stage" style="position:relative;cursor:crosshair"><video id="cameraVideo" autoplay playsinline muted></video><div class="camera-placeholder"><div><div class="cam-icon">◎</div><b style="display:block;margin-top:10px">AR Measurement & Bay Planner</b><small style="display:block;margin-top:6px">Start camera to place AR boundary points or estimate lot size</small></div></div><div class="ar-hud"><div class="ar-capsule" id="arMeasureStatus">TAP STAGE TO PLACE CORNER POINTS (0/4)</div><div class="ar-boundary" id="arBoundaryVisual"></div><div class="ar-cross"></div><div id="arTapePoints"></div></div></div><div class="ar-controls"><button class="button" data-action="camera-start">◎ Start camera</button><button class="button outline" data-action="ar-add-point">📍 Add corner pin</button><button class="button ghost" data-action="ar-reset-points">↺ Clear pins</button><button class="button lime" data-action="ar-apply-measured-bays">⚡ Auto-generate bays from AR</button><button class="button outline" data-action="camera-stop">Stop</button></div><p class="footer-note"><b>How AR Measuring Works:</b> Walk along your lot or tap the live camera view at the corners to establish boundary pins. ParkAR computes the real-world distance in meters and estimates optimal bay capacity.</p></section><section class="panel"><h3 class="section-title">Lot dimensions & bay generator</h3><form id="measurementForm" class="listing-form" style="margin-top:14px"><input type="hidden" name="listing_id" value="${l.id}"><div class="field"><label>Width (m)</label><input class="input" id="measureWidth" name="width_m" type="number" min="1" step="0.1" value="${l.width_m||'15.0'}" required></div><div class="field"><label>Length (m)</label><input class="input" id="measureLength" name="length_m" type="number" min="1" step="0.1" value="${l.length_m||'30.0'}" required></div><div class="field full"><label>Measurement source</label><select name="source"><option value="camera_estimate">AR camera-assisted estimate</option><option value="manual">Manual tape measurement</option></select></div><div class="field full"><label>Notes</label><textarea name="notes" placeholder="e.g. Measured via rear camera ground plane"></textarea></div><button class="button">Confirm dimensions</button></form><hr style="border:0;border-top:1px solid var(--line);margin:16px 0"><div class="panel-head"><div><h4 class="section-title" style="font-size:13px">Bay capacity projection</h4><p class="section-sub" id="arBayEstimateText">Standard 2.5m × 5.0m bays with aisle clearance</p></div></div><button class="button lime small" style="width:100%" data-action="ar-apply-measured-bays">Generate & apply bay layout</button></section></div>`}
function membershipsView(){return `<div class="row"><div><h2 class="section-title">Exclusive memberships</h2><p class="section-sub">Reserve specific bays for eligible customers across a date range.</p></div><button class="button" data-action="new-membership">+ Assign membership</button></div><div class="panel" style="margin-top:16px"><div id="membershipList" class="empty">Loading memberships…</div></div>`}
function applicationRow(a){return `<div class="queue-item"><div class="queue-symbol">♙</div><div><b>${esc(a.business_name||a.legal_name)}</b><small>${esc(a.user_name||a.user_email)} · ${esc(a.address)} · ${esc(a.contact_phone)}</small></div><div class="queue-actions"><button class="button outline small" data-action="application-decision" data-id="${a.id}" data-decision="reject">Decline</button><button class="button small" data-action="application-decision" data-id="${a.id}" data-decision="approve">Approve</button></div></div>`}
function reviewView(){return `<div class="row"><div><h2 class="section-title">Provider applications</h2><p class="section-sub">Verify providers before granting listing-management access.</p></div></div><div class="admin-queue" style="margin-top:16px">${(state.dashboard.applications||[]).filter(a=>a.status==='pending').map(applicationRow).join('')||'<div class="panel empty">No provider applications are awaiting review.</div>'}</div>`}
function moderateView(){return `<div class="row"><div><h2 class="section-title">Listing review</h2><p class="section-sub">Approve listings before they appear in driver search.</p></div></div><div class="admin-queue" style="margin-top:16px">${listings().filter(l=>l.status==='pending').map(l=>`<div class="queue-item"><div class="queue-symbol">▧</div><div><b>${esc(l.name)}</b><small>${esc(l.provider_name)} · ${esc(l.address)} · ${money(l.hourly_rate)}/hour</small></div><div class="queue-actions"><button class="button outline small" data-action="listing-decision" data-id="${l.id}" data-decision="reject">Return</button><button class="button small" data-action="listing-decision" data-id="${l.id}" data-decision="approve">Approve</button></div></div>`).join('')||'<div class="panel empty">No listings need review.</div>'}</div>`}
function usersView(){return `<div class="row"><div><h2 class="section-title">Platform users & administration</h2><p class="section-sub">Manage user accounts, roles, and create administrator accounts directly.</p></div><button class="button" data-action="create-user">+ Create admin or user account</button></div><div class="panel" style="margin-top:16px"><div class="panel-head"><div><h3 class="section-title">Registered accounts</h3><p class="section-sub">Role-based account access</p></div></div><div id="userList" class="empty">Loading users…</div></div>`}
function reportsView(){return `<div class="stats">${stat('CONFIRMED BOOKINGS','—','Active reservations','▤')}${stat('BOOKING VALUE','—','Recorded reservation total','₱')}${stat('PARKING SPACES','—','Across managed listings','▦')}${stat('NOTIFICATIONS','—','Operational updates','♧')}</div><div class="panel"><h3 class="section-title">Activity summary</h3><div id="reportContent" class="empty">Loading current report…</div></div>`}
function guideView(){return `<div class="row"><div><h2 class="section-title">Indoor guide</h2><p class="section-sub">Scan a lot checkpoint to route from your current position to the assigned bay.</p></div><button class="button outline" data-page="bookings">← Bookings</button></div><div id="guideContent" class="panel" style="margin-top:16px">Loading indoor route…</div>`}
async function loadPageData(){try{if(state.page==='search'){let params=new URLSearchParams();if(state.query)params.set('q',state.query);if(state.city)params.set('city',state.city);if(state.coveredFilter)params.set('covered',state.coveredFilter);state.dashboard.listings=await api(`/listings/?${params}`);render();return}if(state.page==='guide')await loadGuide();if(state.page==='checkpoints')await loadCheckpoints();if(state.page==='pricing')await loadPricing();if(state.page==='memberships')await loadMemberships();if(state.page==='users')await loadUsers();if(state.page==='reports')await loadReports()}catch(e){showToast(e.message)}}
function bind(){document.onclick=event=>{const stage=event.target.closest('#cameraStage');if(stage&&!event.target.closest('button')){addArPoint(event);return}const pageButton=event.target.closest('[data-page]');if(pageButton){state.page=pageButton.dataset.page;render();loadPageData();return}const tab=event.target.closest('[data-auth-tab]');if(tab){setAuthMode(tab.dataset.authTab);return}const close=event.target.closest('[data-close]');if(close){closeModal();return}const action=event.target.closest('[data-action]');if(action)handleAction(action).catch(error=>showToast(error.message))};window.removeEventListener('parkar:open-booking',onOpenBooking);window.addEventListener('parkar:open-booking',onOpenBooking);document.onsubmit=event=>{const form=event.target;if(form.id==='authForm'){event.preventDefault();submitAuth(form).catch(e=>$('#authError').textContent=e.message)}else if(form.id==='forgotForm'){event.preventDefault();requestPasswordReset(form).catch(e=>$('#authError').textContent=e.message)}else if(form.id==='resetForm'){event.preventDefault();confirmPasswordReset(form).catch(e=>$('#authError').textContent=e.message)}else if(form.id==='searchForm'){event.preventDefault();const fd=new FormData(form);state.query=fd.get('q').trim();state.city=fd.get('city').trim();state.coveredFilter=fd.get('covered');state.page='search';loadPageData()}else if(form.id==='bookingForm'){event.preventDefault();submitBooking(form).catch(e=>showToast(e.message))}else if(form.id==='applicationForm'){event.preventDefault();submitApplication(form).catch(e=>showToast(e.message))}else if(form.id==='newListingForm'){event.preventDefault();createListing(form).catch(e=>showToast(e.message))}else if(form.id==='vehicleForm'){event.preventDefault();createVehicle(form).catch(e=>showToast(e.message))}else if(form.id==='measurementForm'){event.preventDefault();saveMeasurement(form).catch(e=>showToast(e.message))}else if(form.id==='priceRuleForm'){event.preventDefault();savePriceRule(form).catch(e=>showToast(e.message))}else if(form.id==='baseRateForm'){event.preventDefault();saveBaseRate(form).catch(e=>showToast(e.message))}else if(form.id==='edgeForm'){event.preventDefault();createEdge(form).catch(e=>showToast(e.message))}else if(form.id==='checkpointForm'){event.preventDefault();createCheckpoint(form).catch(e=>showToast(e.message))}else if(form.id==='membershipForm'){event.preventDefault();createMembership(form).catch(e=>showToast(e.message))}else if(form.id==='createUserForm'){event.preventDefault();submitCreateUser(form).catch(e=>showToast(e.message))}else if(form.id==='profileForm'){event.preventDefault();submitProfileForm(form).catch(e=>showToast(e.message))}else if(form.id==='changeRoleForm'){event.preventDefault();submitChangeRole(form).catch(e=>showToast(e.message))}else if(form.id==='editSpaceForm'){event.preventDefault();saveEditSpace(form).catch(e=>showToast(e.message))}};document.onchange=event=>{if(event.target.id==='listingPicker'){state.selectedListing=listings().find(l=>l.id===event.target.value);render();loadPageData()}if(event.target.id==='guideCheckpoint'){state.guideCheckpoint=event.target.value}}}
function onOpenBooking(event){bookingModal(event.detail.id)}
function setAuthMode(mode){state.authMode=mode;state.authNotice='';if(mode==='login'||mode==='register'){state.resetUid=null;state.resetToken=null;if(location.search.includes('uid=')){history.replaceState({},'',location.pathname)}}render()}
async function submitAuth(form){const fd=new FormData(form),payload=Object.fromEntries(fd.entries());if(state.authMode==='register'){payload.username=payload.username||payload.email;const result=await api('/auth/register/',{method:'POST',body:payload});enter(result)}else{const result=await api('/auth/login/',{method:'POST',body:{email:payload.email,password:payload.password}});enter(result)}}
async function requestPasswordReset(form){const fd=new FormData(form);const result=await api('/auth/password-reset/',{method:'POST',body:{email:fd.get('email')}});if(result.reset_url){state.authNotice=`${result.detail}<br><br><b>Local reset link:</b><br><a href="${result.reset_url}" style="color:#2b6cb0;word-break:break-all;text-decoration:underline;display:inline-block;margin-top:6px;">Click here to set your new password</a>`}else{state.authNotice=result.detail}render()}
async function confirmPasswordReset(form){const fd=new FormData(form),password=String(fd.get('password')||'');if(password!==fd.get('confirm_password'))throw new Error('The passwords do not match.');const result=await api('/auth/password-reset/confirm/',{method:'POST',body:{uid:fd.get('uid'),token:fd.get('token'),password}});history.replaceState({},'',location.pathname);state.authMode='login';state.resetUid=null;state.resetToken=null;state.authNotice=result.detail;render()}
function modal(title,body){$('#modalRoot').innerHTML=`<div class="modal-backdrop" data-close><section class="modal" onclick="event.stopPropagation()"><header class="modal-head"><h2>${esc(title)}</h2><button class="close" data-close aria-label="Close">×</button></header><div>${body}</div></section></div>`}
function closeModal(){$('#modalRoot').innerHTML=''}
function bookingModal(id){const l=listings().find(x=>String(x.id)===String(id));if(!l){showToast('Refresh listings and select a location.');return}const vehicles=state.dashboard.vehicles||[];if(!vehicles.length){showToast('Add a vehicle before reserving a space.');state.page='vehicles';render();return}modal('Reserve a parking space',`<p class="section-sub">${esc(l.name)} · ${money(l.hourly_rate)} per hour</p><form id="bookingForm"><input type="hidden" name="listing_id" value="${l.id}"><div class="field"><label>Vehicles to include</label><div class="vehicle-checks">${vehicles.map(v=>`<label class="vehicle-check"><input type="checkbox" name="vehicle_ids" value="${v.id}"><span><b>${esc(v.name)}</b><small>${esc(v.plate_number)} · ${esc(v.category)}</small></span></label>`).join('')}</div></div><div class="listing-form" style="margin-top:12px"><div class="field"><label>Start date and time</label><input class="input" type="datetime-local" name="starts_at" min="${new Date(Date.now()+3600000).toISOString().slice(0,16)}" required></div><div class="field"><label>End date and time</label><input class="input" type="datetime-local" name="ends_at" required></div></div><div class="field" style="margin-top:12px"><label>Payment method</label><select name="payment_method"><option value="pay_on_site">Pay at parking location</option><option value="manual_transfer">Manual transfer (provider confirms)</option></select></div><p class="footer-note">The server checks space compatibility and overlapping reservations before confirming.</p><button class="button" style="width:100%;margin-top:8px">Confirm reservation</button></form>`)}
function createListingModal(){modal('Create a parking listing',`<form id="newListingForm" class="listing-form"><div class="field full"><label>Parking name</label><input class="input" name="name" required maxlength="140"></div><div class="field full"><label>Description</label><textarea name="description"></textarea></div><div class="field full"><label>Street address</label><input class="input" name="address" required></div><div class="field"><label>City</label><input class="input" name="city" required></div><div class="field"><label>Hourly rate (PHP)</label><input class="input" name="hourly_rate" type="number" min="0.01" step="0.01" required></div><div class="field"><label>Starting bay count</label><input class="input" name="initial_space_count" type="number" min="1" max="130" value="10" required></div><div class="field full"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px"><label style="margin:0">Coordinates (Latitude & Longitude)</label><button type="button" class="button outline small" data-action="get-listing-gps">📍 Use my current location</button></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px"><input class="input" id="newListingLat" name="latitude" type="number" step="0.000001" placeholder="Latitude (e.g. 14.5547)"><input class="input" id="newListingLon" name="longitude" type="number" step="0.000001" placeholder="Longitude (e.g. 121.0244)"></div></div><div class="field"><label>Covered lot?</label><select name="covered"><option value="true">Covered</option><option value="false">Open-air</option></select></div><div class="field"><label>Opening time</label><input class="input" type="time" name="opening_time" value="06:00"></div><div class="field"><label>Closing time</label><input class="input" type="time" name="closing_time" value="22:00"></div><div class="field full"><small class="section-sub">The listing will need administrator approval before it becomes visible to drivers.</small></div><div class="field full"><button class="button">Save listing for review</button></div></form>`)}
function vehicleModal(){modal('Add a vehicle',`<form id="vehicleForm" class="listing-form"><div class="field"><label>Vehicle name</label><input class="input" name="name" placeholder="Toyota Vios" required></div><div class="field"><label>Category</label><select name="category"><option value="motorcycle">Motorcycle</option><option value="car">Car</option><option value="suv">SUV</option><option value="van">Van</option></select></div><div class="field full"><label>Plate number</label><input class="input" name="plate_number" required></div><div class="field"><label>Length (m)</label><input class="input" type="number" name="length_m" step="0.01" min="0.5" value="4.5"></div><div class="field"><label>Width (m)</label><input class="input" type="number" name="width_m" step="0.01" min="0.5" value="1.8"></div><button class="button">Save vehicle</button></form>`)}
async function submitBooking(form){const fd=new FormData(form),vehicleIds=fd.getAll('vehicle_ids').map(Number);if(!vehicleIds.length)throw new Error('Select at least one vehicle.');const starts=new Date(fd.get('starts_at')),ends=new Date(fd.get('ends_at'));if(!(ends>starts))throw new Error('End time must be after start time.');const result=await api('/reservations/',{method:'POST',body:{listing_id:fd.get('listing_id'),vehicle_ids:vehicleIds,starts_at:starts.toISOString(),ends_at:ends.toISOString(),payment_method:fd.get('payment_method')}});closeModal();state.selectedReservation=result.id;state.page='bookings';await refresh();showToast(`Reservation ${result.code} confirmed`)}
async function submitApplication(form){const fd=new FormData(form);await api('/applications/',{method:'POST',body:Object.fromEntries(fd.entries())});await refresh();showToast('Provider application submitted')}
async function createListing(form){const fd=new FormData(form),body=Object.fromEntries(fd.entries());body.covered=body.covered==='true';if(!body.latitude)delete body.latitude;if(!body.longitude)delete body.longitude;const created=await api('/listings/',{method:'POST',body});closeModal();state.selectedListing=created;await refresh();state.page='layout';render();showToast('Listing saved and submitted for review')}
async function createVehicle(form){const fd=new FormData(form),body=Object.fromEntries(fd.entries());body.length_m=Number(body.length_m);body.width_m=Number(body.width_m);await api('/vehicles/',{method:'POST',body});closeModal();await refresh();showToast('Vehicle profile saved')}
async function saveMeasurement(form){const fd=new FormData(form),body=Object.fromEntries(fd.entries());delete body.listing_id;body.width_m=Number(body.width_m);body.length_m=Number(body.length_m);const result=await api(`/listings/${fd.get('listing_id')}/measurements/`,{method:'POST',body});await refresh();state.page='layout';render();showToast(`Dimensions recorded (${result.source})`)}
async function createCheckpoint(form){const fd=new FormData(form),listingId=fd.get('listing_id');const body={action:'checkpoint',checkpoint:{code:fd.get('code').toUpperCase(),label:fd.get('label'),kind:fd.get('kind')}};await api(`/listings/${listingId}/checkpoints/`,{method:'POST',body});closeModal();await loadCheckpoints();showToast('Checkpoint added')}
async function createEdge(form){const fd=new FormData(form),listingId=fd.get('listing_id');await api(`/listings/${listingId}/checkpoints/`,{method:'POST',body:{action:'connect',from_code:fd.get('from_code').toUpperCase(),to_code:fd.get('to_code').toUpperCase(),distance_m:Number(fd.get('distance_m')),instruction:fd.get('instruction'),bidirectional:true}});form.reset();showToast('Indoor route connection saved');await loadCheckpoints()}
async function createMembership(form){const fd=new FormData(form),listingId=fd.get('listing_id'),body={listing_id:listingId,user_id:Number(fd.get('user_id')),space_code:fd.get('space_code').toUpperCase(),starts_at:new Date(fd.get('starts_at')).toISOString(),ends_at:new Date(fd.get('ends_at')).toISOString()};await api('/memberships/',{method:'POST',body});closeModal();await loadMemberships();showToast('Exclusive membership assigned')}
function membershipModal(){const l=selectedProviderListing();if(!l)return;modal('Assign an exclusive space membership',`<form id="membershipForm" class="listing-form"><input type="hidden" name="listing_id" value="${l.id}"><div class="field"><label>Customer account ID</label><input class="input" type="number" name="user_id" min="1" required></div><div class="field"><label>Parking bay code</label><input class="input" name="space_code" required></div><div class="field"><label>Starts</label><input class="input" type="datetime-local" name="starts_at" required></div><div class="field"><label>Ends</label><input class="input" type="datetime-local" name="ends_at" required></div><div class="field full"><button class="button">Assign membership</button></div></form><p class="footer-note">Find account IDs in the administrative user list.</p>`)}
function createUserModal(){modal('Create an account',`<form id="createUserForm" class="listing-form"><div class="field full"><label>Account role</label><select name="role" class="input" required><option value="admin">Administrator (full control)</option><option value="provider">Provider (manage parking listings)</option><option value="driver">Driver (customer)</option></select></div><div class="field full"><label>Email address</label><input class="input" name="email" type="email" placeholder="admin@parkar.local" required></div><div class="field"><label>Username (optional)</label><input class="input" name="username" placeholder="admin"></div><div class="field"><label>Password (min 8 characters)</label><input class="input" name="password" type="password" minlength="8" required></div><div class="field full"><button class="button" style="width:100%">Create account</button></div></form>`)}
async function submitCreateUser(form){const fd=new FormData(form),body=Object.fromEntries(fd.entries());await api('/admin/users/',{method:'POST',body});closeModal();await loadUsers();showToast(`Account created as ${body.role}`)}
function profileModal(){const u=state.user;modal('Account & security settings',`<form id="profileForm" class="listing-form"><div class="field"><label>First name</label><input class="input" name="first_name" value="${esc(u?.first_name||'')}"></div><div class="field"><label>Last name</label><input class="input" name="last_name" value="${esc(u?.last_name||'')}"></div><div class="field full"><label>Phone number</label><input class="input" name="phone" value="${esc(u?.phone||'')}"></div><div class="field full" style="border-top:1px solid #e2e8f0;padding-top:14px;margin-top:6px"><b style="font-size:12px">Change password (optional)</b><small class="section-sub" style="display:block;margin-top:3px">Leave blank to keep your current password</small></div><div class="field full"><label>Current password</label><input class="input" name="current_password" type="password"></div><div class="field full"><label>New password (min 8 characters)</label><input class="input" name="new_password" type="password"></div><div class="field full"><button class="button" style="width:100%">Save changes</button></div></form>`)}
async function submitProfileForm(form){const fd=new FormData(form),body=Object.fromEntries(fd.entries());if(!body.new_password){delete body.new_password;delete body.current_password}else if(!body.current_password){throw new Error('Enter your current password to set a new password.')}const updated=await api('/me/',{method:'PATCH',body});state.user=updated;closeModal();render();showToast('Account details updated')}
function changeRoleModal(id,currentRole){modal('Change account role',`<form id="changeRoleForm" class="listing-form"><input type="hidden" name="user_id" value="${id}"><div class="field full"><label>Select role</label><select name="role" class="input"><option value="driver" ${currentRole==='driver'?'selected':''}>Driver</option><option value="provider" ${currentRole==='provider'?'selected':''}>Provider (manage listings)</option><option value="admin" ${currentRole==='admin'?'selected':''}>Administrator (full control)</option></select></div><div class="field full"><button class="button" style="width:100%">Update role</button></div></form>`)}
async function submitChangeRole(form){const fd=new FormData(form),id=fd.get('user_id'),role=fd.get('role');await api(`/admin/users/${id}/`,{method:'PATCH',body:{role}});closeModal();await loadUsers();showToast(`Role updated to ${role}`)}
function editSpaceModal(id){const l=selectedProviderListing(),s=l?.spaces.find(x=>String(x.id)===String(id));if(!s)return;modal(`Configure bay ${s.code}`,`<form id="editSpaceForm" class="listing-form"><input type="hidden" name="space_id" value="${s.id}"><div class="field"><label>Bay code</label><input class="input" name="code" value="${esc(s.code)}" required></div><div class="field"><label>Vehicle class</label><select name="vehicle_class" class="input"><option value="any" ${s.vehicle_class==='any'?'selected':''}>Any</option><option value="motorcycle" ${s.vehicle_class==='motorcycle'?'selected':''}>Motorcycle</option><option value="car" ${s.vehicle_class==='car'?'selected':''}>Car</option><option value="large" ${s.vehicle_class==='large'?'selected':''}>Large (SUV / Van)</option></select></div><div class="field"><label>Width (m)</label><input class="input" type="number" step="0.1" name="width_m" value="${s.width_m||2.5}"></div><div class="field"><label>Length (m)</label><input class="input" type="number" step="0.1" name="length_m" value="${s.length_m||5}"></div><div class="field full"><button class="button" style="width:100%">Update bay details</button></div></form>`)}
function saveEditSpace(form){const fd=new FormData(form),sId=fd.get('space_id'),l=selectedProviderListing(),s=l?.spaces.find(x=>String(x.id)===String(sId));if(s){s.code=fd.get('code').toUpperCase();s.vehicle_class=fd.get('vehicle_class');s.width_m=Number(fd.get('width_m'));s.length_m=Number(fd.get('length_m'));closeModal();render();showToast(`Bay ${s.code} updated (click 'Save layout' to persist)`)} }
async function ticketModal(reservationId){const t=await api(`/reservations/${reservationId}/ticket/`);modal(`Parking pass · ${t.code}`,`<div style="text-align:center"><div style="margin:10px auto;max-width:180px">${t.pass_qr_svg||''}</div><b style="font-size:16px;display:block">${esc(t.listing_name)}</b><span class="tag" style="margin:6px 0">${esc(t.status.toUpperCase())}</span><div class="summary-box" style="text-align:left;margin-top:12px"><div class="summary-row"><span>Booking code</span><b>${esc(t.code)}</b></div><div class="summary-row"><span>Assigned bay(s)</span><b>${(t.assignments||[]).map(a=>esc(a.code)).join(', ')||'Pending'}</b></div><div class="summary-row"><span>Schedule</span><b>${fmtDate(t.starts_at)}<br>to ${fmtDate(t.ends_at)}</b></div><div class="summary-row"><span>Vehicle(s)</span><b>${(t.vehicles||[]).map(v=>esc(v.vehicle_name)+' ('+esc(v.plate_number)+')').join(', ')||'—'}</b></div><div class="summary-row total"><span>Total fee</span><b>${money(t.total)}</b></div></div><button class="button" style="width:100%;margin-top:14px" onclick="window.print()">🖨 Print / save pass</button></div>`)}
async function previewLayoutModal(listingId){const data=await api(`/listings/${listingId}/layout/`);const l=data.listing,spaces=data.spaces||[];modal(`${esc(l.name)} · bay availability`,`<p class="section-sub">${esc(l.address)} · ${spaces.length} configured spaces</p><div class="space-grid" style="margin-top:14px">${spaces.map(s=>`<div class="space ${s.slot_status==='blocked'?'occupied':''} ${s.slot_status==='reserved'?'reserved':''} ${s.is_accessible?'accessible':''}" style="cursor:default">${esc(s.code)}<small>${esc(s.vehicle_class||'any')}</small></div>`).join('')||'<div class="empty">No bays configured.</div>'}</div><div class="legend" style="margin-top:14px"><span>Available</span><span>Reserved</span><span>Blocked</span></div><button class="button" style="width:100%;margin-top:16px" data-action="book" data-id="${l.id}">Reserve a bay</button>`)}
function getProviderListingGps(){if(!navigator.geolocation){showToast('Geolocation is not supported in this browser.');return}showToast('Acquiring high-accuracy GPS coordinates…');navigator.geolocation.getCurrentPosition(pos=>{const lat=pos.coords.latitude.toFixed(6),lon=pos.coords.longitude.toFixed(6);const latIn=$('#newListingLat'),lonIn=$('#newListingLon');if(latIn)latIn.value=lat;if(lonIn)lonIn.value=lon;showToast(`Location set: ${lat}, ${lon}`)},err=>{showToast('Could not retrieve location. Please allow location permissions in your browser.')},{enableHighAccuracy:true,timeout:10000})}
state.arPoints=state.arPoints||[];
function addArPoint(e){const stage=$('#cameraStage');if(!stage)return;const rect=stage.getBoundingClientRect();let px=50,py=50;if(e&&e.clientX){px=Math.round(((e.clientX-rect.left)/rect.width)*100);py=Math.round(((e.clientY-rect.top)/rect.height)*100)}else{const offsets=[[20,25],[80,20],[85,80],[15,85]];const idx=state.arPoints.length%4;px=offsets[idx][0];py=offsets[idx][1]}state.arPoints.push({x:px,y:py});renderArMeasurementVisuals()}
function resetArPoints(){state.arPoints=[];renderArMeasurementVisuals();showToast('AR boundary pins cleared')}
function renderArMeasurementVisuals(){const container=$('#arTapePoints'),status=$('#arMeasureStatus'),bound=$('#arBoundaryVisual');if(!container||!status)return;container.innerHTML=state.arPoints.map((pt,i)=>`<div style="position:absolute;left:${pt.x}%;top:${pt.y}%;transform:translate(-50%,-50%);width:22px;height:22px;border-radius:50%;background:#c5f06a;color:#17382c;font:800 11px Arial;display:grid;place-items:center;border:2px solid #17382c;box-shadow:0 0 10px #c5f06a;z-index:3">${i+1}</div>`).join('');const count=state.arPoints.length;status.textContent=`AR CORNERS PLACED: ${count} / 4`;if(bound&&count>=3){const pts=state.arPoints.map(p=>`${p.x}% ${p.y}%`).join(', ');bound.style.clipPath=`polygon(${pts})`;bound.style.display='block'}if(count>=2){const p1=state.arPoints[0],p2=state.arPoints[1];const estW=Math.max(8,Math.min(60,Math.round(Math.abs(p2.x-p1.x)*0.35+8)));let estL=Math.max(12,Math.min(100,Math.round(estW*1.8)));if(count>=3){const p3=state.arPoints[2];estL=Math.max(10,Math.min(90,Math.round(Math.abs(p3.y-p2.y)*0.45+12)))}const wIn=$('#measureWidth'),lIn=$('#measureLength');if(wIn)wIn.value=estW.toFixed(1);if(lIn)lIn.value=estL.toFixed(1);const baysTotal=Math.floor(estW/2.5)*Math.max(1,Math.floor((estL-6)/5))*2;const txt=$('#arBayEstimateText');if(txt)txt.textContent=`Estimated dimensions: ${estW}m W × ${estL}m L → ~${Math.max(4,baysTotal)} optimal parking bays with central aisle.`}}
async function applyMeasuredBays(){const l=selectedProviderListing();if(!l)return showToast('Select a parking lot first.');const wIn=Number($('#measureWidth')?.value)||l.width_m||15,lIn=Number($('#measureLength')?.value)||l.length_m||30;const cols=Math.max(2,Math.min(8,Math.floor(wIn/2.8))),baysPerCol=Math.max(2,Math.min(25,Math.floor(lIn/5.2)));const spaces=[];let bayNum=1;for(let c=0;c<cols;c++){const rowChar=String.fromCharCode(65+c);for(let r=0;r<baysPerCol;r++){spaces.push({id:`ar-${Date.now()}-${bayNum}`,code:`${rowChar}${r+1}`,status:'available',is_accessible:(r===0&&c===0),vehicle_class:'any',width_m:'2.50',length_m:'5.00',grid_row:c,grid_column:r});bayNum++}}l.spaces=spaces;l.width_m=wIn;l.length_m=lIn;await api(`/listings/${l.id}/measurements/`,{method:'POST',body:{width_m:wIn,length_m:lIn,source:'camera_estimate',notes:'Auto-generated bay layout via AR camera boundary mapping'}});await api(`/listings/${l.id}/layout/`,{method:'PUT',body:{spaces:spaces.map((s,i)=>({code:s.code,status:s.status,is_accessible:Boolean(s.is_accessible),vehicle_class:s.vehicle_class,width_m:s.width_m,length_m:s.length_m,grid_row:s.grid_row,grid_column:s.grid_column})),width_m:wIn,length_m:lIn}});await refresh();state.selectedListing=listings().find(x=>x.id===l.id);state.page='layout';render();showToast(`AR applied: ${spaces.length} bays configured across ${wIn}m × ${lIn}m lot!`)}
async function loadCheckpoints(){let l=selectedProviderListing();if(!l)return;const result=await api(`/listings/${l.id}/checkpoints/`);const el=$('#checkpointList');if(!el)return;el.innerHTML=result.checkpoints.length?`<table class="table"><thead><tr><th>CHECKPOINT</th><th>CODE</th><th>QR PAYLOAD</th><th>ACTION</th></tr></thead><tbody>${result.checkpoints.map(c=>`<tr><td><b>${esc(c.label)}</b><small>${esc(c.kind)}</small></td><td>${esc(c.code)}</td><td><div class="qr-marker"><img src="${esc(c.qr_image_url)}" alt="QR marker for ${esc(c.label)}"><code>${esc(c.marker_value)}</code></div><button class="text-link" data-action="copy" data-value="${esc(c.marker_value)}">Copy payload</button> <button class="text-link" data-action="print-qr" data-url="${esc(c.qr_image_url)}" data-label="${esc(c.label)}">Print marker</button></td><td><button class="button danger small" data-action="delete-checkpoint" data-id="${esc(c.code)}">Delete</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No checkpoints configured. Save a parking layout to generate entrance, aisle, and bay points.</div>'}
async function loadGuide(){const id=state.selectedReservation,b=bookings().find(x=>String(x.id)===String(id));const el=$('#guideContent');if(!el)return;if(!b){el.innerHTML='<div class="empty">Select a confirmed reservation to open the indoor guide.</div>';return}const listingId=b.listing,checkpoint=state.guideCheckpoint||localStorage.getItem(`parkar-checkpoint-${listingId}`)||'ENTRANCE';const result=await api(`/reservations/${b.id}/indoor-route/?from=${encodeURIComponent(checkpoint)}`);state.guideRoute=result;const points=(result.steps||[]).map((s,i)=>`<div class="indoor-node ${i===0?'current':''} ${i===result.steps.length-1?'destination':''}"><span>${i===result.steps.length-1?'P':i+1}</span><div><b>${esc(s.label)}</b><small>${esc(s.instruction)}</small></div></div>`).join('');el.innerHTML=`<div class="guide-content-grid"><section><div class="ar-stage" id="guideStage"><video id="guideVideo" autoplay playsinline muted></video><div class="camera-placeholder"><div><div class="cam-icon">◎</div><b style="display:block;margin-top:10px">Indoor guide · Bay ${(b.assignments||[]).map(a=>esc(a.code)).join(', ')}</b><small style="display:block;margin-top:6px">Scan a checkpoint marker to update your starting point</small></div></div><div class="ar-hud guide-hud"><div class="ar-capsule">DESTINATION · ${(b.assignments||[]).map(a=>esc(a.code)).join(', ')}</div><div class="guide-arrow">↑</div><div class="guide-reticle"><span>${esc(result.target)}</span></div><div class="guide-caption">${esc(result.steps[0]?.instruction||'Arrive at your assigned space.')}</div></div></div><div class="ar-controls"><button class="button" data-action="guide-camera">▦ Scan QR checkpoint</button><button class="button outline" data-action="enable-heading">◎ Enable compass arrow</button><button class="button ghost" data-action="guide-camera-stop">Stop camera</button></div><p class="footer-note">Scan QR markers placed at lot entrances and aisles. Between scans, use the route steps and follow posted signs.</p></section><section><div class="summary-box"><div class="summary-row"><span>Reservation</span><b>${esc(b.code)}</b></div><div class="summary-row"><span>Location</span><b>${esc(b.listing_name)}</b></div><div class="summary-row"><span>Current checkpoint</span><b>${esc(checkpoint)}</b></div><div class="summary-row"><span>Assigned bay</span><b>${(b.assignments||[]).map(a=>esc(a.code)).join(', ')}</b></div></div><div class="field" style="margin-top:14px"><label>Set checkpoint manually</label><select id="guideCheckpoint">${(await api(`/listings/${b.listing}/checkpoints/`)).checkpoints.map(c=>`<option value="${esc(c.code)}" ${c.code===checkpoint?'selected':''}>${esc(c.label)}</option>`).join('')}</select><button class="button small" style="margin-top:8px" data-action="set-checkpoint">Update route</button></div><div class="indoor-path" style="margin-top:14px"><small>ROUTE · ABOUT ${esc(result.distance_m)} METRES</small>${points}</div><div class="route-box"><small>Assigned spaces</small><div class="route-line">${(b.assignments||[]).map(a=>`<span class="tag">${esc(a.code)}</span>`).join(' ')}</div></div></section></div>`;const stage=$('#guideStage'),video=$('#guideVideo');if(state.camera&&stage&&video){video.srcObject=state.camera;stage.classList.add('live')}updateGuideArrow()}
async function loadMemberships(){const result=await api('/memberships/');const el=$('#membershipList');if(!el)return;el.innerHTML=result.length?`<table class="table"><thead><tr><th>CUSTOMER</th><th>LOT</th><th>SPACE</th><th>PERIOD</th><th>STATUS</th></tr></thead><tbody>${result.map(m=>`<tr><td>${esc(m.user)}</td><td>${esc(m.listing_name)}</td><td>${esc(m.space)}</td><td>${fmtDate(m.starts_at)} – ${fmtDate(m.ends_at)}</td><td>${m.active?'Active':'Expired'}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No memberships are assigned.</div>'}
