async function handleAction(button){const action=button.dataset.action,id=button.dataset.id;if(action==='logout')return logout();if(action==='book')return bookingModal(id);if(action==='add-vehicle')return vehicleModal();if(action==='new-listing')return createListingModal();if(action==='guide'){state.selectedReservation=id;state.page='guide';render();return loadGuide()}if(action==='cancel'){if(!confirm('Cancel this reservation?'))return;await api(`/reservations/${id}/cancel/`,{method:'POST',body:{}});await refresh();showToast('Reservation cancelled');return}if(action==='remove-vehicle'){if(!confirm('Remove this vehicle profile?'))return;await api(`/vehicles/${id}/`,{method:'DELETE'});await refresh();showToast('Vehicle removed');return}if(action==='select-listing')return selectListing(id);if(action==='choose-listing')return applyCheckpoint();if(action==='edit-checkpoints'){state.selectedListing=listings().find(l=>l.id===id);state.page='checkpoints';render();return loadCheckpoints()}if(action==='add-space')return addSpace();if(action==='toggle-accessible')return toggleAccessible(id);if(action==='cycle-space')return cycleSpace(id);if(action==='save-layout')return saveLayout();if(action==='application-decision'){await api(`/applications/${id}/decision/`,{method:'POST',body:{decision:button.dataset.decision}});await refresh();showToast('Application reviewed');return}if(action==='listing-decision'){await api(`/listings/${id}/moderate/`,{method:'POST',body:{decision:button.dataset.decision}});await refresh();showToast('Listing status updated');return}if(action==='add-checkpoint')return checkpointModal();if(action==='set-checkpoint'){const code=$('#guideCheckpoint')?.value;if(!code)return;state.guideCheckpoint=code;localStorage.setItem(`parkar-checkpoint-${bookings().find(b=>String(b.id)===String(state.selectedReservation))?.listing}`,code);return loadGuide()}if(action==='guide-camera')return scanGuideMarker();if(action==='enable-heading')return enableHeading();if(action==='guide-camera-stop')return stopCamera();if(action==='camera-start')return startCamera('cameraStage','cameraVideo');if(action==='camera-stop')return stopCamera();if(action==='get-listing-gps')return getProviderListingGps();if(action==='ar-add-point')return addArPoint();if(action==='ar-reset-points')return resetArPoints();if(action==='ar-apply-measured-bays')return applyMeasuredBays();if(action==='new-membership')return membershipModal();if(action==='delete-price-rule'){const l=selectedProviderListing();if(l&&confirm('Delete this pricing rule?')){await api(`/listings/${l.id}/pricing/${id}/`,{method:'DELETE'});await loadPricing();showToast('Pricing rule deleted')}return}if(action==='mark-paid'){await api(`/payments/${id}/status/`,{method:'POST',body:{status:'paid'}});await refresh();showToast('Payment recorded as collected');return}if(action==='external-route')return openExternalRoute(id);if(action==='route-preview')return routePreview(id);if(action==='select-map'){state.selectedListing=listings().find(l=>l.id===id);return showToast(`Selected ${state.selectedListing?.name||'parking location'}`)}if(action==='locate')return locateNearby();if(action==='notifications')return notificationsModal();if(action==='copy'){const value=button.dataset.value||'';if(!navigator.clipboard?.writeText){showToast('Clipboard access is unavailable. Select and copy the checkpoint code instead.');return}await navigator.clipboard.writeText(value);showToast('Checkpoint marker value copied');return}if(action==='print-qr')return printQr(button.dataset.url,button.dataset.label);if(action==='apply-checkpoint')return applyCheckpoint();if(action==='create-user')return createUserModal();if(action==='account-settings')return profileModal();if(action==='toggle-user-active'){await api(`/admin/users/${id}/`,{method:'PATCH',body:{active:button.dataset.active==='true'}});await loadUsers();showToast('User status updated');return}if(action==='change-user-role')return changeRoleModal(id,button.dataset.role);if(action==='delete-checkpoint'){const l=selectedProviderListing();if(l&&confirm(`Delete checkpoint ${id}?`)){await api(`/listings/${l.id}/checkpoints/${id}/`,{method:'DELETE'});await loadCheckpoints();showToast('Checkpoint removed')}return}if(action==='edit-space')return editSpaceModal(id);if(action==='delete-space'){const l=selectedProviderListing();if(l){l.spaces=l.spaces.filter(s=>String(s.id)!==String(id));render();showToast('Bay removed (click Save layout to confirm)')}return}if(action==='ticket')return ticketModal(id);if(action==='view-layout-preview')return previewLayoutModal(id)}
function selectListing(id){if(id){state.selectedListing=listings().find(l=>l.id===id);state.page='layout';render();return}if(listings().length===1){state.selectedListing=listings()[0];render();loadPageData();return}modal('Choose a parking listing',`<div class="field"><label>Listing</label><select id="chooseListing">${listings().map(l=>`<option value="${l.id}">${esc(l.name)} · ${esc(l.status)}</option>`).join('')}</select></div><button class="button" style="margin-top:12px" data-action="choose-listing">Manage listing</button>`)}
function rowLabel(index){let number=index+1,label='';while(number){number-=1;label=String.fromCharCode(65+number%26)+label;number=Math.floor(number/26)}return label}
function addSpace(){const l=selectedProviderListing();if(!l)return;const spaces=l.spaces||[],row=Math.max(0,...spaces.map(s=>Number(s.grid_row)||0)),existing=spaces.filter(s=>s.grid_row===row),next=existing.reduce((n,s)=>Math.max(n,Number(s.grid_column)+1),0);spaces.push({id:`new-${Date.now()}`,code:`${rowLabel(row)}${next+1}`,status:'available',is_accessible:false,vehicle_class:'any',width_m:'2.50',length_m:'5.00',grid_row:row,grid_column:next});l.spaces=spaces;render()}
function cycleSpace(id){const l=selectedProviderListing(),s=l?.spaces.find(x=>String(x.id)===String(id));if(!s)return;s.status=s.status==='available'?'blocked':'available';render()}
function toggleAccessible(id){const l=selectedProviderListing(),s=l?.spaces.find(x=>String(x.id)===String(id));if(s){s.is_accessible=!s.is_accessible;render()}}
async function saveLayout(){const l=selectedProviderListing();if(!l)return;const spaces=(l.spaces||[]).map((s,i)=>({code:s.code,status:s.status,is_accessible:Boolean(s.is_accessible),vehicle_class:s.vehicle_class||'any',width_m:s.width_m||2.5,length_m:s.length_m||5,grid_row:s.grid_row??Math.floor(i/5),grid_column:s.grid_column??i%5}));await api(`/listings/${l.id}/layout/`,{method:'PUT',body:{spaces,width_m:l.width_m,length_m:l.length_m}});await refresh();state.selectedListing=listings().find(x=>x.id===l.id);state.page='layout';render();showToast('Parking layout saved')}
function checkpointModal(){const l=selectedProviderListing();if(!l)return;modal('Add indoor checkpoint',`<form id="checkpointForm" class="listing-form"><input type="hidden" name="listing_id" value="${l.id}"><div class="field"><label>Checkpoint code</label><input class="input" name="code" placeholder="ROW-C" required></div><div class="field"><label>Type</label><select name="kind"><option value="aisle">Aisle</option><option value="entrance">Entrance</option><option value="stair">Stairs</option><option value="elevator">Elevator</option></select></div><div class="field full"><label>Sign label</label><input class="input" name="label" placeholder="Row C aisle marker" required></div><div class="field full"><button class="button">Save checkpoint</button></div></form>`)}
async function applyCheckpoint(){const code=$('#chooseListing')?.value;if(code){state.selectedListing=listings().find(l=>l.id===code);closeModal();render();loadPageData()}}
function updateGuideArrow(){const arrow=$('.guide-arrow');const bearing=state.guideRoute?.steps?.[0]?.bearing_deg;if(!arrow||bearing===null||bearing===undefined)return;const heading=state.deviceHeading??0,relative=((Number(bearing)-heading)%360+360)%360;arrow.style.transform=`translateX(-50%) rotate(${relative}deg)`;arrow.title=`Next direction ${Math.round(relative)} degrees from current phone heading`}
async function enableHeading(){try{const orientation=window.DeviceOrientationEvent;if(!orientation){showToast('Compass orientation is not supported on this device or PC. Follow the route steps.');return}if(typeof orientation.requestPermission==='function'){const permission=await orientation.requestPermission();if(permission!=='granted'){showToast('Motion/orientation permission was denied.');return}}let received=false;if(!state.headingHandler){state.headingHandler=event=>{let heading;if(Number.isFinite(event.webkitCompassHeading))heading=event.webkitCompassHeading;else if(Number.isFinite(event.alpha))heading=(360-event.alpha)%360;if(Number.isFinite(heading)){received=true;state.deviceHeading=heading;updateGuideArrow()}};window.addEventListener('deviceorientationabsolute',state.headingHandler,true);window.addEventListener('deviceorientation',state.headingHandler,true)}setTimeout(()=>{if(!received&&!('ontouchstart' in window)){showToast('No physical compass hardware detected on this PC. Use route steps on desktop, or open on mobile.')}else{showToast('Compass arrow active. Keep the device level.')}},800)}catch(error){showToast('Compass is unavailable on this device. Follow the route steps.')}}
function stopHeading(){if(state.headingHandler){window.removeEventListener('deviceorientationabsolute',state.headingHandler,true);window.removeEventListener('deviceorientation',state.headingHandler,true);state.headingHandler=null}state.deviceHeading=null}
function printQr(url,label){const w=window.open('','_blank','width=520,height=640');if(!w){showToast('Allow pop-ups to print QR markers.');return}w.document.write(`<!doctype html><html><head><title>ParkAR checkpoint · ${esc(label)}</title><style>body{font-family:Arial,sans-serif;text-align:center;padding:30px;color:#17382c}img{width:320px;height:320px}h1{font-size:22px}p{color:#607266;font-size:13px}</style></head><body><h1>${esc(label)}</h1><img src="${esc(url)}"><p>ParkAR indoor checkpoint<br>Place this marker at the signed location.</p><button onclick="print()">Print</button></body></html>`);w.document.close()}
async function startCamera(stageId,videoId){if(!navigator.mediaDevices?.getUserMedia){showToast('Camera needs a supported browser on HTTPS or localhost.');return}try{if(state.camera)stopCamera();state.camera=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});const stage=$(`#${stageId}`),video=$(`#${videoId}`);if(video)video.srcObject=state.camera;stage?.classList.add('live');showToast('Camera started')}catch(e){showToast(e.name==='NotAllowedError'?'Camera access was denied.':'Could not start the device camera.')}}
function stopCamera(){if(state.qrFrame)cancelAnimationFrame(state.qrFrame);state.qrFrame=0;state.camera?.getTracks().forEach(track=>track.stop());state.camera=null;document.querySelectorAll('.ar-stage').forEach(el=>el.classList.remove('live'))}
async function scanGuideMarker(){
  if(!('BarcodeDetector'in window)){
    const b=bookings().find(x=>String(x.id)===String(state.selectedReservation));
    const manual=prompt('Browser does not support live video BarcodeDetector. Enter or scan QR checkpoint code manually (e.g. ENTRANCE, JUNCTION, ROW-A):', state.guideCheckpoint||'ENTRANCE');
    if(manual&&b){
      let code=manual.trim();
      const parsed=code.match(/^PARKAR\|([^|]+)\|([^|]+)$/i);
      if(parsed)code=parsed[2];
      state.guideCheckpoint=code.toUpperCase();
      localStorage.setItem(`parkar-checkpoint-${b.listing}`,state.guideCheckpoint);
      await loadGuide();
      showToast(`Checkpoint updated: ${state.guideCheckpoint}`);
    }
    return;
  }
  try{
    const formats=await BarcodeDetector.getSupportedFormats();
    if(!formats.includes('qr_code'))throw new Error('QR scanning is not supported.');
    await startCamera('guideStage','guideVideo');
    if(!state.camera)return;
    const detector=new BarcodeDetector({formats:['qr_code']}),video=$('#guideVideo'),b=bookings().find(x=>String(x.id)===String(state.selectedReservation));
    const scan=async()=>{
      if(!state.camera||!video)return;
      if(video.readyState<2){state.qrFrame=requestAnimationFrame(scan);return}
      try{
        for(const c of await detector.detect(video)){
          const parsed=String(c.rawValue||'').trim().match(/^PARKAR\|([^|]+)\|([^|]+)$/i);
          if(parsed&&b&&parsed[1]===String(b.listing)){
            state.guideCheckpoint=parsed[2].toUpperCase();
            localStorage.setItem(`parkar-checkpoint-${b.listing}`,state.guideCheckpoint);
            stopCamera();
            await loadGuide();
            showToast(`Checkpoint found: ${state.guideCheckpoint}`);
            return;
          }
        }
      }catch{}
      state.qrFrame=requestAnimationFrame(scan);
    };
    state.qrFrame=requestAnimationFrame(scan);
    showToast('Scan the QR marker posted at this checkpoint');
  }catch(e){showToast(e.message)}
}
async function saveBaseRate(form){const fd=new FormData(form),l=listings().find(x=>String(x.id)===fd.get('listing_id'));if(!l)return;await api(`/listings/${l.id}/`,{method:'PATCH',body:{hourly_rate:Number(fd.get('hourly_rate'))}});await refresh();state.page='pricing';render();await loadPricing();showToast('Base rate updated')}
async function savePriceRule(form){const fd=new FormData(form),listingId=fd.get('listing_id'),body=Object.fromEntries(fd.entries());body.hourly_rate=Number(body.hourly_rate);body.discount_percent=Number(body.discount_percent||0);body.active=body.active==='true';if(!body.start_time)body.start_time=null;if(!body.end_time)body.end_time=null;await api(`/listings/${listingId}/pricing/`,{method:'POST',body});form.reset();await loadPricing();showToast('Pricing rule saved')}
async function loadPricing(){const l=selectedProviderListing(),el=$('#priceRuleList');if(!l||!el)return;const rules=await api(`/listings/${l.id}/pricing/`);el.innerHTML=rules.length?`<table class="table"><thead><tr><th>RULE</th><th>VEHICLES</th><th>RATE</th><th>DISCOUNT</th><th>TIME WINDOW</th><th></th></tr></thead><tbody>${rules.map(r=>`<tr><td><b>${esc(r.name)}</b><small>${r.active?'Active':'Inactive'}</small></td><td>${esc(r.vehicle_category||'All')}</td><td>${money(r.hourly_rate)}/hr</td><td>${r.discount_percent}%</td><td>${r.start_time||'Any'} – ${r.end_time||'Any'}</td><td><button class="button danger small" data-action="delete-price-rule" data-id="${r.id}">Delete</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No vehicle-specific pricing rules.</div>'}
function routePathD(){const pts=state.routeData?.geometry?.coordinates;if(!pts||pts.length<2)return '';const xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys),rx=maxX-minX||1e-6,ry=maxY-minY||1e-6;return pts.map((p,i)=>`${i?'L':'M'} ${50+(p[0]-minX)/rx*700} ${30+(maxY-p[1])/ry*360}`).join(' ')}
async function routePreview(id){const l=listings().find(x=>String(x.id)===String(id));if(!l)return;if(!l.latitude||!l.longitude){showToast('Provider has not added coordinates. You can still open the lot in a map app.');return openExternalRoute(id)}if(!navigator.geolocation){showToast('Location permission is required for route estimates.');return}navigator.geolocation.getCurrentPosition(async pos=>{try{state.routeData=await api(`/routes/?listing_id=${l.id}&origin_lat=${pos.coords.latitude}&origin_lon=${pos.coords.longitude}`);state.page='map';render();showToast(`Route ready · ${(state.routeData.distance_m/1000).toFixed(1)} km · ${Math.round(state.routeData.duration_s/60)} min`)}catch(e){showToast(`${e.message} Opening your map app.`);openExternalRoute(id)}},()=>showToast('Location permission was not granted.'),{enableHighAccuracy:true,timeout:12000})}
function openExternalRoute(id){const l=listings().find(x=>x.id===id);if(!l)return;if(l.latitude&&l.longitude)window.open(`https://www.google.com/maps/dir/?api=1&destination=${l.latitude},${l.longitude}`,'_blank','noopener');else showToast('This listing needs map coordinates for external directions.')}
function locateNearby(){if(!navigator.geolocation){showToast('Location is not available in this browser.');return}navigator.geolocation.getCurrentPosition(pos=>{const nearest=listings().filter(l=>l.latitude&&l.longitude).map(l=>({l,d:Math.hypot(Number(l.latitude)-pos.coords.latitude,Number(l.longitude)-pos.coords.longitude)})).sort((a,b)=>a.d-b.d)[0];if(nearest){state.selectedListing=nearest.l;showToast(`Nearest listed lot: ${nearest.l.name}`)}else showToast('No geocoded active listings to compare.')},()=>showToast('Location permission was not granted.'),{enableHighAccuracy:true,timeout:10000})}
function notificationsModal(){const items=state.dashboard.notifications||[];modal('Notifications',items.length?items.map(n=>`<div class="booking-item"><div class="booking-icon">♧</div><div class="booking-info"><b>${esc(n.title)}</b><small>${esc(n.message)} · ${fmtDate(n.created_at)}</small></div></div>`).join(''):'<div class="empty">No notifications yet.</div>');api('/notifications/read-all/',{method:'POST',body:{}}).then(()=>refresh()).catch(()=>{})}
